{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "PET imaging in baboons showed that [11C]10, a close arylpiperazine-butyl-dione analogue, crossed the BBB and produced regional brain uptake matching 5-HT1A receptor distribution; its high transfer score makes this directly applicable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "FECUMI-101, a fluoroethyl analogue of CUMI-101 with the same arylpiperazine-butyl-dione core, effectively crossed the BBB in baboon PET studies.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "NGB 2904, an arylpiperazine-butyl amide with a lipophilic dichlorophenyl piperazine, entered the brain quickly and showed high brain penetration after IV administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In mice, [123I]-BPB, an arylpiperazine-butyl benzamide, showed high brain uptake of 4.99 %ID/g at 10 min, indicating ready BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "PET studies in baboons confirmed that [11C]5, a methoxyphenylpiperazine-butyl dione analogue, penetrates the BBB, despite suboptimal tracer kinetics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "d-Norfenfluramine, a lipophilic CF3-containing basic amine, showed free and rapid brain distribution with a brain/plasma AUC ratio of about 40 in rats, supporting that CF3 and basic nitrogen do not preclude CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. The query is a CF3-phenylpiperazine-butyl xanthine; multiple close analogues with the same arylpiperazine-butyl heterocycle pharmacophore were directly shown to cross the BBB in PET/biodistribution studies across baboon, rat, and mouse. These high-transfer experimental results outweigh the uncertain physicochemical prior of high MW, ionization, and possible efflux.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Efflux-transporter phenotype of the query is not experimentally characterized.",
    "No human CNS exposure data for this exact scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

